        "content": "设立居住权，当事人应当采用书面形式订立居住权合同。居住权合同一般包括下列条款：（一）当事人的姓名或者名称和住所；（二）住宅的位置；（三）居住的条件和要求；（四）居住权期限；（五）解决争议的方法。"
