        "num_int": 1,
        "content": "为了加强和规范开发区人大工作，促进开发区高质量发展、高效能治理，根据《中华人民共和国地方各级人民代表大会和地方各级人民政府组织法》、《中华人民共和国各级人民代表大会常务委员会监督法》、《中华人民共和国全国人民代表大会和地方各级人民代表大会代表法》等法律、法规，结合本市实际，制定本条例。"
