        "content": "乡镇人民政府、街道办事处在辖区范围内出现突发性暴雨灾害或者接收到暴雨临灾预警叫应时，应当立即组织开展先期处置，落实分级防御措施，并立即报告县（市、区）人民政府。暴雨灾害发生地的村民委员会、居民委员会和其他组织应当按照当地人民政府的决定、命令，进行宣传动员，组织群众开展自救与互救，协助维护社会秩序；情况紧急的，应当立即组织群众开展自救、互救等先期处置工作。受暴雨灾害影响严重的单位和个人，在收到预警信号之前，可以主动采取必要的紧急避险措施，保障人员安全。"
