        "content": "市、旗县区人民政府负责本行政区域内旅游安全管理工作，组织编制旅游突发事件应急预案，开展应急演练，加强对旅游活动产生重大影响的自然灾害和社会突发事件的监测预警，及时妥善处理旅游安全突发事件和旅游安全事故。文化和旅游、公安、生态环境、交通运输、水行政、卫生健康、应急管理、市场监督管理、体育、林业和草原、气象、消防救援等部门和单位，应当依法履行旅游安全监督管理职责，改进日常监督管理方式，在重大文化旅游活动和预防自然灾害期间等重要节点集中组织开展安全检查。"
